package ru.folio.notes;

import java.util.*;
import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import javax.imageio.ImageIO;
import java.io.File;

/** Production math plus independent references. No Android drawing/window claims. */
public final class CanvasUpgradeTests {
    static int assertions;static Random random=new Random(81021);
    static void check(boolean value,String label){if(!value)throw new AssertionError(label);assertions++;}
    static void names(){TimeZone old=TimeZone.getDefault();try{TimeZone.setDefault(TimeZone.getTimeZone("UTC"));Calendar c=Calendar.getInstance();c.clear();c.set(2026,9,21,1,0);Date date=c.getTime();
        check(NotebookNames.unique("  ",Collections.emptyList(),date).equals("21.10.2026"),"blank name is local date");
        check(NotebookNames.unique("",Arrays.asList("21.10.2026","21.10.2026 (1)","21.10.2026 (3)"),date).equals("21.10.2026 (2)"),"first available collision suffix");
        check(NotebookNames.unique("  Эскиз ",Arrays.asList("эскиз","Эскиз (1)"),date).equals("Эскиз (2)"),"trim and case-insensitive explicit title collision");
        TimeZone.setDefault(TimeZone.getTimeZone("America/New_York"));check(NotebookNames.unique(null,Collections.emptyList(),date).equals("20.10.2026"),"date follows current timezone, not UTC");
    }finally{TimeZone.setDefault(old);}System.out.println("PASS blank/date titles, suffix holes, Cyrillic names and local timezone");}
    static void tools(){ToolColors state=new ToolColors();state.put("pen",0xff102030);state.put("brush",0xffabcdef);state.put("eraser",0xffee0000);check(state.get("pen",0)==0xff102030&&state.get("brush",0)==0xffabcdef,"colors are isolated");check(!state.saved.containsKey("eraser")&&!ToolColors.enabled("eraser"),"eraser cannot own a color");check(ToolColors.enabled("line")&&ToolColors.enabled("laser")&&!ToolColors.enabled("hand"),"drawing guides and laser have ink, navigation does not");}
    static void gradient(){for(int i=0;i<20000;i++){float h=random.nextFloat()*360,s=random.nextFloat(),v=random.nextFloat();ColorModel model=new ColorModel(0xff000000);model.hue=h;model.gradient(s,v);int expected=Color.HSBtoRGB(h/360,s,v),actual=model.color();for(int shift:new int[]{0,8,16})check(Math.abs((actual>>shift&255)-(expected>>shift&255))<=1,"gradient HSV agrees with independent RGB reference");check(Math.abs(model.vividness()-s)<.0001f&&Math.abs(model.value()-v)<.0001f,"gradient handle round trip");}
        ColorModel model=new ColorModel(0xff0000ff);model.gradient(.8f,0);check(model.color()==0xff000000&&Math.abs(model.vividness()-.8f)<.0001,"black keeps horizontal gradient position");model.gradient(.8f,1);check(model.color()!=0xff000000,"moving up from black restores color");model.gradient(0,1);check(model.color()==0xffffffff,"top-left white");System.out.println("PASS continuous gradient, white/black and retained chroma with no slider UI");}
    static void ruler(){RulerGeometry ruler=new RulerGeometry();for(int i=0;i<4000;i++){ruler.x=(random.nextFloat()-.5f)*10000;ruler.y=(random.nextFloat()-.5f)*10000;ruler.degrees=random.nextFloat()*360-180;Ink.Pt point=new Ink.Pt(ruler.x+(random.nextFloat()-.5f)*2000,ruler.y+(random.nextFloat()-.5f)*2000,1,0,0),projected=ruler.project(point);check(Math.abs(ruler.localY(projected.x,projected.y))<.001,"projection on rotated ruler edge");check(Math.abs(ruler.localX(projected.x,projected.y)-ruler.localX(point.x,point.y))<.001,"infinite projection preserves longitudinal position");}
        check(Math.abs(PaperSizes.CM-96/2.54f)<.0001,"ruler cm and custom millimeters share 96 dpi");check(Math.abs(PaperSizes.SIZES[1][0]/PaperSizes.SIZES[1][1]-210f/297)<.0001,"A4 dimensions");check(PaperSizes.valid(200,10000)&&!PaperSizes.valid(199,500)&&!PaperSizes.valid(Float.NaN,1000),"custom size bounds and finite values");check(PaperSizes.COLORS[0]==0xffffffff&&PaperSizes.COLORS[1]==0xfffffaf0&&PaperSizes.COLORS[2]==0xff000000,"reference Mi Canvas paper colors");check(PaperSizes.linesFor(0xff000000)==0x4dffffff&&PaperSizes.linesFor(0xffffffff)==0x4d000000,"black/white paper contrast");System.out.println("PASS rotated ruler projection, measurement units, page presets and paper reference colors");}
    static Ink.Stroke stroke(String tool,int n){Ink.Stroke s=new Ink.Stroke();s.tool=tool;s.width=12;for(int i=0;i<n;i++)s.points.add(new Ink.Pt(i*1.3f,100+(float)Math.sin(i*.08)*25,.2f+random.nextFloat(),random.nextFloat(),i*.04f));return s;}
    static void hits(){for(String tool:new String[]{"pen","brush","fountain","pencil","marker","tape","rainbow"}){Ink.Stroke s=stroke(tool,400);StrokeChunks chunks=new StrokeChunks(s);for(int j=0;j<700;j++){float x=random.nextFloat()*550-20,y=60+random.nextFloat()*80,r=random.nextFloat()*10;check(chunks.hit(s,x,y,r)==s.hit(x,y,r),"chunked stationary hit matches original "+tool);}
            int segments=0;for(StrokeChunks.Chunk chunk:chunks.chunks)segments+=chunk.to-chunk.from-1;check(segments==s.points.size()-1,"blocks contain every segment exactly once");
        }
        SpatialIndex index=new SpatialIndex();Ink.Stroke original=stroke("pen",10000);index.add(original,17);Ink.Stroke clipped=original.copy();clipped.cuts.add(new Ink.Cut(100,100,30,200,100));StrokeChunks retained=index.entries.get(original).geometry;index.replaceMask(original,clipped);check(index.entries.get(clipped).geometry==retained&&index.entries.get(clipped).order==17,"mask replacement reuses immutable hit geometry");check(!index.entries.containsKey(original)&&index.actions.get(original.action).contains(clipped),"cell/action identity replaced");check(index.query(50,50,250,150).contains(clipped),"replacement query");
        Ink.Cut mask=new Ink.Cut(0,0,10,100,0);check(mask.covers(50,0,10)&&!mask.covers(50,1,10)&&mask.covers(105,0,4),"swept mask is a continuous circle path");Ink.Stroke s=new Ink.Stroke();s.points.add(new Ink.Pt(0,0,1,0,0));s.cuts.add(mask);Ink.Cut moved=s.translated(20,30).cuts.get(0);check(moved.x==20&&moved.y==30&&moved.z==120&&moved.w==30,"translation keeps both swept endpoints");Ink.Cut rotated=s.transformed(0,0,2,(float)Math.PI/2).cuts.get(0);check(Math.abs(rotated.z)<.001&&Math.abs(rotated.w-200)<.001&&rotated.r==20,"transformation keeps mask endpoints and radius");check(s.copy().cuts.get(0)==mask,"immutable mask can be shared safely in history");System.out.println("PASS hit parity, complete segment coverage, indexed mask replacement and swept-mask transforms");}
    static void angleAndArcs(){
        for(float target:RulerGeometry.ANGLES)for(float offset:new float[]{-2.9f,-1,0,1,2.9f}){RulerGeometry r=new RulerGeometry();r.rotate(target+offset);check(Math.abs(RulerGeometry.angle(r.degrees-target))<.001,"angle magnet in every quadrant");check(Float.isFinite(r.snapTarget),"snap highlight active");r.rotate(target+4.9f);check(Math.abs(RulerGeometry.angle(r.degrees-target))<.001,"hysteresis retains snap");r.rotate(target+6);check(!Float.isFinite(r.snapTarget),"leaving snap is smooth");}
        for(float target:new float[]{(float)Math.PI,-(float)Math.PI,(float)Math.PI/2,-(float)Math.PI/3,(float)Math.PI*2})for(float start:new float[]{0,.8f,3.1f,-3.1f}){
            Ink.Stroke stroke=new Ink.Stroke();CompassTrace trace=new CompassTrace();trace.begin(stroke,210,-110,140,210+155*(float)Math.cos(start),-110+155*(float)Math.sin(start));
            check(stroke.points.size()==1,"compass does not generate an arc on pen down");
            for(int n=1;n<=80;n++){float angle=start+target*n/80;trace.move(stroke,210+(150+n%8)*(float)Math.cos(angle),-110+(150+n%8)*(float)Math.sin(angle));}
            Ink.Pt first=stroke.points.get(0),last=stroke.points.get(stroke.points.size()-1);check(Math.abs(trace.sweep-target)<.001,"manual angle unwrap in either direction");check(Math.abs(last.x-(210+140*Math.cos(start+target)))<.001&&Math.abs(last.y-(-110+140*Math.sin(start+target)))<.001,"arc stops where the user stops");
            for(Ink.Pt point:stroke.points)check(Math.abs(Ink.dist(point.x,point.y,210,-110)-140)<.001,"hand wobble cannot change fixed compass radius");
            if(Math.abs(target)==(float)Math.PI)check(Math.abs(Ink.dist(first.x,first.y,last.x,last.y)-280)<.001,"manually traced semicircle ends opposite its start");
            int before=stroke.points.size();float reverse=start+target*.5f;trace.move(stroke,210+140*(float)Math.cos(reverse),-110+140*(float)Math.sin(reverse));check(stroke.points.size()>before,"reversing direction retains earlier ink");int count=stroke.points.size();trace.move(stroke,210,-110);check(stroke.points.size()==count,"undefined direction at center does not add a jump");trace.clear();trace.move(stroke,100,100);check(stroke.points.size()==count,"released compass cannot append ink");
        }System.out.println("PASS 16 ruler magnets with hysteresis; manually traced semicircles/arcs/circles, fixed radius, reversal and release");
    }
    static void benchmark(){Ink.Stroke s=stroke("pen",100000);StrokeChunks chunks=new StrokeChunks(s);float x=s.points.get(99950).x,y=s.points.get(99950).y;
        for(int i=0;i<30;i++){s.hit(x,y,5);chunks.hit(s,x,y,5);}long[] slow=new long[5],fast=new long[5];for(int run=0;run<5;run++){long start=System.nanoTime();for(int i=0;i<200;i++)if(!s.hit(x,y,5))throw new AssertionError();slow[run]=System.nanoTime()-start;start=System.nanoTime();for(int i=0;i<200;i++)if(!chunks.hit(s,x,y,5))throw new AssertionError();fast[run]=System.nanoTime()-start;}Arrays.sort(slow);Arrays.sort(fast);System.out.printf(Locale.ROOT,"DESKTOP ONLY: 100000-point stroke, 200 end-region hits; median full scan %.2f ms, indexed blocks %.2f ms (%.1fx). Not tablet latency or FPS.%n",slow[2]/1e6,fast[2]/1e6,slow[2]/(double)fast[2]);}
    static void preview(String file)throws Exception{BufferedImage image=new BufferedImage(960,540,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(0x12151b));g.fillRect(0,0,960,540);g.setFont(new Font("SansSerif",Font.BOLD,24));g.setColor(Color.WHITE);g.drawString("Folio 1.8 - gradient and measured ruler",35,43);g.setFont(new Font("SansSerif",0,13));g.setColor(new Color(0x9ca6b8));g.drawString("Desktop data/layout illustration - not an Android screenshot",35,69);
        float cx=195,cy=278,radius=138;for(int n=0;n<720;n++){g.setColor(Color.getHSBColor(n/720f,1,1));g.setStroke(new BasicStroke(27));double a=n*Math.PI/360;g.draw(new Arc2D.Float(cx-radius,cy-radius,radius*2,radius*2,-n/2f,-1,Arc2D.OPEN));}
        for(int y=0;y<170;y++)for(int x=0;x<170;x++)image.setRGB(110+x,193+y,Color.HSBtoRGB(.62f,x/169f,1-y/169f));
        g.setColor(new Color(0xe8eef7));g.fill(new RoundRectangle2D.Float(382,187,530,105,12,12));g.setStroke(new BasicStroke(1));g.setColor(new Color(0x34425b));g.setFont(new Font("SansSerif",0,12));for(int mm=0;mm<=140;mm++){float x=386+mm*3.72f;g.draw(new Line2D.Float(x,188,x,188+(mm%10==0?29:mm%5==0?20:12)));if(mm%10==0)g.drawString(""+(mm/10),x-3,234);}g.setFont(new Font("SansSerif",Font.BOLD,14));g.drawString("0.0 degrees / cm",585,274);
        for(int i=0;i<3;i++){g.setColor(new Color(PaperSizes.COLORS[i]));g.fill(new RoundRectangle2D.Float(386+i*177,352,160,90,12,12));}g.setColor(new Color(0x9ca6b8));g.setFont(new Font("SansSerif",0,13));g.drawString("Mi Canvas paper presets: white / warm yellow / black",386,475);g.dispose();ImageIO.write(image,"png",new File(file));}
    public static void main(String[] args)throws Exception{names();tools();gradient();ruler();hits();angleAndArcs();benchmark();preview(args[0]);System.out.println("PASS "+assertions+" canvas upgrade assertions; desktop model only");}
}
